INSERT INTO "source_slug_links" ("ref_id", "slug", "local_ref_id", "created_at", "created_by_session", "updated_at", "updated_by_session", "relevance_note") VALUES ('REF-01037', 'accessible-bathroom-and-grab-bar', '1', '2026-11-13 21:44', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 21:44', 'session_2026-11-13-edmonton-checklist-pass', 'Item 8.6 states the accessible washroom stall (minimum 1700 mm x 1500 mm, toilet height 400 to 460 mm, grab bars, an outward-swinging door); item 8.5 sink, mirror and dispenser heights.');
INSERT INTO "source_slug_links" ("ref_id", "slug", "local_ref_id", "created_at", "created_by_session", "updated_at", "updated_by_session", "relevance_note") VALUES ('REF-01037', 'luminance-contrast-and-pattern', '1', '2026-11-13 21:44', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 21:44', 'session_2026-11-13-edmonton-checklist-pass', 'The source requires colour contrast at many elements (items 1.2, 2.10, 4.1, 4.7, 5.1, 5.5, 6.4, 7.2, 9.8, 11.2) and states no luminance or reflectance figure for it.');
INSERT INTO "source_slug_links" ("ref_id", "slug", "local_ref_id", "created_at", "created_by_session", "updated_at", "updated_by_session", "relevance_note") VALUES ('REF-01037', 'reach-range-and-accessible-controls', '1', '2026-11-13 21:44', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 21:44', 'session_2026-11-13-edmonton-checklist-pass', 'Items 2.8, 5.4, 9.1, 9.3, 9.4 and 9.5 state mounting heights for door buttons, elevator controls, phones, a drinking fountain, a counter and light switches.');
INSERT INTO "source_slug_links" ("ref_id", "slug", "local_ref_id", "created_at", "created_by_session", "updated_at", "updated_by_session", "relevance_note") VALUES ('REF-01037', 'stair-ramp-threshold-biomechanics-accessibility', '4', '2026-11-13 21:44', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 21:44', 'session_2026-11-13-edmonton-checklist-pass', 'Item 6.1 states ramp slopes (1 in 20, a preferred maximum of 1 in 16, 1 in 12 attributed to the Alberta building code) and item 6.2 a 9 m landing interval; item 2.9 a 13 mm threshold rise; item 4.3 stair rise and run.');
INSERT INTO "source_slug_links" ("ref_id", "slug", "local_ref_id", "created_at", "created_by_session", "updated_at", "updated_by_session", "relevance_note") VALUES ('REF-01037', 'threshold-door-hardware', '1', '2026-11-13 21:44', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 21:44', 'session_2026-11-13-edmonton-checklist-pass', 'Item 2.3 states doorway clearance (850 mm, 920 mm preferred), 2.4 lever handles, 2.8 an automatic door operator button height, 2.9 a 13 mm threshold rise.');
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "language") VALUES ('GAP-103', 'SW', 'P2', 'OPEN', NULL, NULL, 'The source marks every statement as Code (required) or Best Practice by text colour (legend on its PDF p. 1), and the figure-level distinction it draws (for example item 1.2: the path is Code, the 1500 mm minimum width is Best Practice) has no typed column on source_value_extractions. It was recorded in notes only (REF-01037 extractions). Found by REF-01037; a schema question for a tooling pull request. || CORRECTED 2026-11-13: The gap as filed proposed a typed Code-versus-Best-Practice column. Owner correction 2026-11-13: best practice is the guidebook determination (the most accommodating or forgiving value or approach across all values for a term), not a label on an input, so no column named best practice is wanted at this stage. The distinction the source draws is, for the guidebook, code floor versus above code floor: its Code (required) statements restate what it attributes to the Alberta building code (the floor) and its Best Practice statements are the committee own recommendations beyond that floor. Open: whether that is a typed property of a figure at all or is derived against the code stratum (rule 8), and what a figure from a non-regulatory source that restates the floor is called.', '2026-11-13 21:45', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 21:56', 'session_2026-11-13-edmonton-checklist-pass', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "language") VALUES ('GAP-104', 'SW', 'P3', 'OPEN', NULL, NULL, 'log-search demands a subject (--slug, --parameter or --mined-ref-id) even for --origin owner-supplied, where no search ran; REF-01037 was logged against parameter 3 only to satisfy the writer. Also log-mining cannot record a deferred forward direction once the backward pass has set citation_mining_status to mined (GAP-015, GAP-022 unruled). Found while admitting REF-01037.', '2026-11-13 21:45', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 21:45', 'session_2026-11-13-edmonton-checklist-pass', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "language") VALUES ('GAP-105', 'DEC', 'P2', 'OPEN', NULL, NULL, 'Does the source colour contrast (the source requires it at many elements, with no figure) name the catalogue LRV contrast concept? Adjudicated DEFERRED on REF-01037 (observed term colour contrast); the owner decides whether it is TERM-011 or a distinct concept.', '2026-11-13 21:45', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 21:45', 'session_2026-11-13-edmonton-checklist-pass', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "language") VALUES ('GAP-106', 'DEC', 'P2', 'OPEN', NULL, NULL, 'Which identity code states a figure when the item names no group: REF-01037 figures for ramp slope, corridor width, headroom and landing interval were tagged ALL on the warrant "meet the needs of all users" (the source purpose statement on its PDF p. 1), and the door width and turning figures MOB on the source own sentence about wheelchairs and scooters. The owner or the lens ruling confirms or corrects these tags.', '2026-11-13 21:45', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 21:45', 'session_2026-11-13-edmonton-checklist-pass', NULL, NULL, NULL, NULL, NULL, NULL, 'ALL', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "language") VALUES ('GAP-107', 'EG', 'P2', 'OPEN', NULL, NULL, 'REF-01037 states figures and requirements for many concepts the catalogue holds no parameter for, adjudicated DEFERRED and not minted (OR-17 leaves minting to the data pull request the owner reads). Derive the list: select o.surface_form, o.locator from observed_terms o join term_adjudications a using (observation_id) where o.ref_id = "REF-01037" and a.outcome = "DEFERRED".', '2026-11-13 21:45', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 21:45', 'session_2026-11-13-edmonton-checklist-pass', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "language") VALUES ('GAP-108', 'EG', 'P3', 'OPEN', NULL, NULL, 'REF-01037 is a City of Edmonton document and its figures are recorded under country code CA: base_jurisdictions holds no sub-national code for Alberta or Edmonton (T-024 built the registry; add-jurisdiction admits one with an approval reference).', '2026-11-13 21:45', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 21:45', 'session_2026-11-13-edmonton-checklist-pass', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'CA', NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "language") VALUES ('GAP-109', 'RP', 'P2', 'OPEN', NULL, NULL, 'Backward-mining leads named by REF-01037 and staged REFERENCE-ONLY, not retrieved: the Safety Codes Council Barrier-Free Design Guide (Aug 2019 PDF), the City of Edmonton Access Design Guide, Policy C602, and the Alberta Building Code (no edition stated). The Barrier-Free Design Guide and the Alberta code edition are the likely holders of the dimensions REF-01037 asserts; derive the leads: select ref_id, title from source_locators where recovered_from like "REF-01037%".', '2026-11-13 21:45', 'session_2026-11-13-edmonton-checklist-pass', '2026-11-13 21:45', 'session_2026-11-13-edmonton-checklist-pass', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
